import type {Column, PersonalViews, Row} from './harness'

// Reserved IDs cannot be generated by table columnId(). Never persist these in table schemas.
export const SYSTEM_COLUMNS: Column[] = [
  {id:'$row.id',name:'ID',type:'text'},
  {id:'$row.createdAt',name:'作成日時',type:'text'},
  {id:'$row.updatedAt',name:'更新日時',type:'text'},
]
export const SYSTEM_COLUMN_IDS = SYSTEM_COLUMNS.map(c=>c.id)
export const isSystemColumn = (id:string) => SYSTEM_COLUMN_IDS.includes(id)
export function displayLayout(columns:Column[], layout?:PersonalViews['layouts'][string]) {
  const all=[...columns,...SYSTEM_COLUMNS], ids=all.map(c=>c.id)
  const order=[...new Set([...(layout?.order||[]).filter(id=>ids.includes(id)),...ids])]
  // Older saved layouts did not know about system fields: preserve their appearance.
  const hidden=[...new Set([...(layout?.hidden||[]),...SYSTEM_COLUMN_IDS.filter(id=>!layout?.order?.includes(id))])].filter(id=>ids.includes(id)&&id!==columns[0]?.id)
  return {columns:all,order,hidden,widths:layout?.widths||{},...(layout?.wrapText ? {wrapText:true} : {})}
}
export function systemCellText(row:Row,id:string) {
  if(id==='$row.id') return row.id
  const value=id==='$row.createdAt'?row.createdAt:row.updatedAt
  if(!value) return '—'
  const date=new Date(value)
  return Number.isFinite(date.getTime()) ? new Intl.DateTimeFormat('ja-JP',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(date) : '—'
}

export const isSystemTimestamp = (id:string) => id==='$row.createdAt'||id==='$row.updatedAt'
export function localDateTime(value:string) {
 const date=new Date(value)
 if(!value||!Number.isFinite(date.getTime())) return ''
 const pad=(n:number)=>String(n).padStart(2,'0')
 return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`
}
export function utcDateTime(value:string) {
 const date=new Date(value)
 return value&&Number.isFinite(date.getTime())?date.toISOString():''
}
export const nextColumnSort = (current:string|undefined,id:string) => current===id?`-${id}`:current===`-${id}`?'':id
